entries[371622] = { ["name"] = "Residualer Wirkstoff der Neuralkanalisierung", ["text"] = "40 Meter Reichweite\nSofort 5 min Abklingzeit\nGreift, wenn Ihr tot seid, das Bewusstsein Eures Gegners mit dem Rest Eures eigenen Bewusstseins an und fügt Eurem Ziel im Verlauf von 18 Sek. [Quellwert] Naturschaden zu. Solltet Ihr wiederbelebt werden, wird der verbleibende Schaden dem Ziel sofort zugefügt. Das Freilassen Eures Geists bewirkt, dass Euer Bewusstsein zu Euch zurückkehrt und der Effekt aufgehoben wird.\n\nTeilt sich eine Abklingzeit mit Gefechtstränken.", ["unresolvedValues"] = true }
entries[371624] = { ["name"] = "Leitfähiges Zeichen", ["text"] = "Unbegrenzte Reichweite\nSofort\nDathea zeichnet den Spielercharakter mit Blitzen, fügt ihm so 70663 Naturschaden sowie alle 1 Sek. 31798 Naturschaden zu und erhöht den erlittenen Naturschaden um 8%. Dieser Effekt ist stapelbar.\n\nInnerhalb von 5 Metern um andere Spielercharaktere wird ' Leitfähiges Zeichen ' dupliziert und erneuert. Innerhalb von 5 Metern um eine Irdene Säule erfolgt eine Erdung und das Zeichen wird gebannt." }
