entries[371836] = { ["name"] = "Urzeitlicher Blizzard", ["text"] = "300 Meter Reichweite\nSofort\nWenn Kadros 100 Energie erreicht, beschwört er 10 Sek. lang einen eiskalten Sturm. Der eisige Wind verursacht alle 1 Sek. 7066 Frostschaden und erhöht 15 Sek. lang den erlittenen Frostschaden um 10%. Dafür verringert er so lange den erlittenen Feuerschaden um 10%. Dieser Effekt ist stapelbar. ' Verbrannter Boden ' entfernt diesen Effekt.\n\nNach 10 Anwendungen werden Spielercharaktere in einem ' Frostgrab ' gefangen." }
entries[371838] = { ["name"] = "Rückruf", ["text"] = "100 Meter Reichweite\nSofort\nReist durch die Zeit zurück zu Eurem Ausgangsort." }
entries[371839] = { ["name"] = "Schöpfungsfunke", ["text"] = "Unbegrenzte Reichweite\nSofort\nLädt einen Spielercharakter für 30 Sek. auf und fügt ihm alle 1 Sek. 3 kosmischen Schaden zu. Dieser Effekt ist stapelbar.\n\nBei Entfernung wirft diese Ladung Schöpfungsfunken auf Positionen in der Nähe ab, die Spielercharaktere innerhalb von 0 Metern um den Einschlag erfüllen. Dies beschleunigt den Zeitstrom um 30 %, was das Zauber- und Angriffstempo, die Abklingzeitrate und die Rate regelmäßiger Ticks erhöht. Zusätzlich wird die Bewegungsgeschwindigkeit um ( 30 + 25 )% erhöht. Hält 20 Sek. lang an. Dieser Effekt ist stapelbar.\n\nFalls ein Schöpfungsfunke auf den Boden aufschlägt und kein Spielercharakter vorhanden ist, der erfüllt werden kann, explodiert der Funke und verursacht 20 Sek. lang alle 2 Sek. 7 kosmischen Schaden. Dieser Effekt ist stapelbar." }
entries[371840] = { ["name"] = "Rekonfigurationsemitter", ["text"] = "Unbegrenzte Reichweite\nSofort\nManifestiert einen angreifbaren Gegner, der kontinuierlich Zauber einsetzt. Dieser Gegner ist bis zum ersten abgeschlossenen Einsatz oder zur ersten erfolgreichen Unterbrechung immun gegen Schaden. Erfolgreiche Einsätze fügen allen Spielercharakteren 30 kosmischen Schaden zu. Der verursachte Schaden des Emitters erhöht sich alle 5 Sek. um 0 %. Dieser Effekt ist stapelbar.\n\nWenn er erfolgreich unterbrochen wird, gibt der Emitter Strahlung ab und fügt allen Spielercharakteren 5 kosmischen Schaden zu.\n\nWenn dieser Gegner besiegt wird, erfüllt er alle Spielercharaktere abhängig vom Energieniveau des Emitters mit Macht. Erhöht die Meisterschaft um bis zu 10 , die kritische Trefferchance um bis zu 10 %, die Vielseitigkeit um bis zu 10 % und die Vermeidung um bis zu 9 ." }
